private fun handleUserInputState(state: UserInputRequiredState) {
    return when (state) {
        is DownloadRetryRequired -> {
            displayDownloadRetryDialog(state)
        }
        is LowStorageAcknowledgementRequired -> {
            displayLowStorageDialog()
        }

private fun displayDownloadRetryDialog(state: DownloadRetryRequired) {
    val reason = state.safeMessage.ifBlank {
        getString(R.string.download_retry_message_generic)
    }
    val builder = AlertDialog.Builder(this)
        .setTitle(R.string.download_retry_title)
        .setMessage(getString(R.string.download_retry_message, reason))
        .setPositiveButton(R.string.button_retry) { dialog, _ ->
            dialog.dismiss()
            viewModel.retryDownloads()
        }
        // Cancel keeps the verified payloads on disk and returns to selection.
        .setNegativeButton(R.string.button_cancel) { dialog, _ ->
            dialog.dismiss()
            viewModel.cancelSetup()
        }
    if (state.canRepair) {
        builder.setNeutralButton(R.string.button_repair) { dialog, _ ->
            dialog.dismiss()
            viewModel.repairFilesystem()
        }
    }
    builder.setCancelable(false).create().show()
}

